// CException_AC.h// Copyright © 1985-2001 by Apple Computer. All rights reserved. /*	Change History		07/27/01	Added unused parameter.		03/09/01	[PP] Work with LException. 		01/02/01	Update copyright.		10/30/00	Split off CSourceLocation_AC, CTerminateHandler_AC and					CMacException_AC from CException_AC. 					Use OSStatus instead of CError_AC for errors. 					Use a typedef for the terminate handler type. 					Remove the fgDoThrowMessage and fgDoCatchMessage flags and					the methods for setting them. They were not being used. 					Remove backward compatible message and error fields. 					Add ThrowIfBadAlloc_AC. Change ThrowIfNULL_AC to call					ThrowIfBadAlloc_AC. Change ThrowIfOSErr_AC and 					ThrowIfBadOSStatus_AC to call ThrowIfError_AC. 					Rename DebugDoCatchISOMessage_AC to DoCatchISOMessage and					DebugDoCatchForeignMessage_AC to DoCatchForeignMessage. 					Remove DebugThrowBadCast_AC. 					Add wrapper functions for throwing the standard C++					exceptions from bad_alloc to underflow_error. 		09/21/00	[W] Use a macro to determine which terminate_handler					is going to be used.		04/03/00	Added ThrowIfBadOSStatus_AC and DebugThrowIfBadOSStatus_AC.		01/04/00	Use only std version of exception and terminate_handler. 		12/27/99	Stripped out unused code.		12/07/99	Include exception in all cases.  Added throw specifier to dtor.					Filename can only be 32 chars for MrC and SCPP.  ~CException_AC					and what are no longer inline.		03/24/99	Update copyright notice.		03/19/99	Rename GetMessage to GetExceptionMessage					since it conflicts with a Windows define.		11/12/98	[2279223] Include <exception> instead of <exception.h>.		10/06/98	Clean up includes. */#ifndef __CException_AC__#define __CException_AC__// ACS#ifndef __Types_AC__#include "Types_AC.h"#endif// PowerPlant#ifdef __PowerPlant__	#ifndef _H_LException	#include <LException.h>	#endif#endif// ANSI#ifndef _EXCEPTION#include <exception>#endif #ifndef __climits__#include <limits.h>#endif//----------------------------------------------------------------------------------------// Max and min error numbers//----------------------------------------------------------------------------------------enum{	minErr = SHRT_MIN,	maxErr = SHRT_MAX,	minACErr = LONG_MIN,	maxACErr = LONG_MAX};//========================================================================================// CSourceLocation_AC//========================================================================================class EXPORT_AC CSourceLocation_AC{public:	CSourceLocation_AC();	CSourceLocation_AC(const char* inFile, short inLine);	CSourceLocation_AC(const CSourceLocation_AC& inEx);	~CSourceLocation_AC() {}		// operators	CSourceLocation_AC& operator = (const CSourceLocation_AC& inEx);		bool operator == (const CSourceLocation_AC& inEx) const;	bool operator != (const CSourceLocation_AC& inEx) const;	void SetLocation(const char* inFile, short inLine);	void SetFile(const char* inFile);	const char* GetFile() const	{ return fFile; }	short GetLine() const	{ return fLine; }			protected:#if defined(__MRC__) || defined(__SC__)	char 			fFile[32];#else	char 			fFile[256];#endif	short			fLine;};//========================================================================================// CTerminateHandler_AC//========================================================================================class EXPORT_AC CTerminateHandler_AC{public:#if _MSC_VERtypedef terminate_handler		terminate_handler_type;#elsetypedef std::terminate_handler	terminate_handler_type;#endif	CTerminateHandler_AC();	CTerminateHandler_AC(terminate_handler_type inHandler);	~CTerminateHandler_AC() {}	private:	static void Default();protected:	static terminate_handler_type fgPrevious;};//========================================================================================// CMacException_AC//========================================================================================class EXPORT_AC CMacException_AC : public#ifdef __PowerPlant__	PP_PowerPlant::LException#else	std::exception#endif{public:	CMacException_AC();	CMacException_AC(OSStatus inError);	CMacException_AC(const CMacException_AC& inEx);	virtual ~CMacException_AC() throw();	#ifndef __PowerPlant__	// operators	CMacException_AC& operator = (const CMacException_AC& inEx);		bool operator == (const CMacException_AC& inEx) const;	bool operator != (const CMacException_AC& inEx) const;#endif	// error	OSStatus GetError() const	{#ifdef __PowerPlant__		return mErrorCode;#else		return fError;#endif	}	virtual void SetError(OSStatus inError);		// overides 		virtual const char* what() const throw();	// Debug Methods#if qDebugExceptions >= qDebugLevelTwo_AC	virtual void DoThrowMessage();	virtual void DoCatchMessage(const char* fileName,								short lineNum,								bool breakInDebugger = false);		// keep going by default.	static void DoCatchISOMessage(const char* inFile,								  short inLine,								  std::exception& ex,								  bool breakInDebugger = false);		// Catch ISO exception messages.	static void DoCatchForeignMessage(const char* inFile,									  short inLine,									  bool breakInDebugger = false);		// Catch foreign exception messages.#endif#ifndef __PowerPlant__protected:	OSStatus 	fError;#endif};//========================================================================================// CException_AC//========================================================================================class EXPORT_AC CException_AC : public CMacException_AC#if qDebugExceptions	, public CSourceLocation_AC#endif{public:	typedef long Message;	CException_AC();	CException_AC(OSStatus inError, Message inMessage = 0);#if qDebugExceptions	CException_AC(OSStatus inError, const char* inFile, short inLine);	CException_AC(OSStatus inError, Message inMessage, const char* inFile, short inLine);#endif	CException_AC(const CException_AC& inEx);	virtual ~CException_AC() throw();		// operators	CException_AC& operator = (const CException_AC& inEx);		bool operator == (const CException_AC& inEx) const;	bool operator != (const CException_AC& inEx) const;	// overides 		virtual const char* what() const throw();	// optional message	Message GetExceptionMessage() const	{ return fMessage; }	void SetMessage(Message inMessage);	void SetMessage(short lowWord, short highWord);	static long BuildMessage(short lowWord, short highWord);	// Debug Methods#if qDebugExceptions	void SetThrownFrom(const char* inFile, short inLine)	{ return SetLocation(inFile, inLine); }#endif			#if qDebugExceptions >= qDebugLevelTwo_AC	virtual void DoThrowMessage();	virtual void DoCatchMessage(const char* fileName,								short lineNum,								bool breakInDebugger = false);		// keep going by default.#endifprotected:	Message 	fMessage;};// helper macros#if qDebugExceptions//------------------------------------------------------------------------------------// Debug Functions//------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// ThrowException_AC//----------------------------------------------------------------------------------------#define ThrowException_AC(err, msg) DebugThrowException_AC(err, msg, __FILE__, __LINE__)EXPORT_AC void DebugThrowException_AC(OSStatus inErr, CException_AC::Message msg,									  const char *inFileName, short inLineNum);//----------------------------------------------------------------------------------------// ThrowIfError_AC//----------------------------------------------------------------------------------------#define ThrowIfError_AC(e) DebugThrowIfError_AC((e), __FILE__, __LINE__)EXPORT_AC void DebugThrowIfError_AC(OSStatus inErr, const char* inFile, short inLine);//----------------------------------------------------------------------------------------// ThrowError_AC//----------------------------------------------------------------------------------------#define ThrowError_AC(e) DebugThrowError_AC((e),  __FILE__, __LINE__)EXPORT_AC void DebugThrowError_AC(OSStatus inErr, const char* inFile, short inLine);//----------------------------------------------------------------------------------------// ThrowIfMemError_AC//----------------------------------------------------------------------------------------#define ThrowIfMemError_AC() DebugThrowIfMemError_AC(__FILE__, __LINE__)EXPORT_AC void DebugThrowIfMemError_AC(const char* inFile, short inLine);//----------------------------------------------------------------------------------------// ThrowIfNULLResource_AC//----------------------------------------------------------------------------------------#define ThrowIfNULLResource_AC(r) DebugThrowIfNULLResource_AC(r, __FILE__, __LINE__)EXPORT_AC void DebugThrowIfNULLResource_AC(const void* r, const char *inFileName, short inLineNum);//----------------------------------------------------------------------------------------// ThrowIfOSErr_AC//----------------------------------------------------------------------------------------#define ThrowIfOSErr_AC(e) DebugThrowIfError_AC(e, __FILE__, __LINE__)//----------------------------------------------------------------------------------------// ThrowIfBadOSStatus_AC//----------------------------------------------------------------------------------------#define ThrowIfBadOSStatus_AC(e) DebugThrowIfError_AC(e, __FILE__, __LINE__)//----------------------------------------------------------------------------------------// ThrowIfNonObject_AC//----------------------------------------------------------------------------------------#define ThrowIfNonObject_AC(obj) DebugThrowIfNonObject_AC(obj, __FILE__, __LINE__)EXPORT_AC void DebugThrowIfNonObject_AC(const void* obj, const char *inFileName, short inLineNum);//----------------------------------------------------------------------------------------// ThrowIfResError_AC//----------------------------------------------------------------------------------------#define ThrowIfResError_AC() DebugThrowIfResError_AC(__FILE__, __LINE__)EXPORT_AC void DebugThrowIfResError_AC(const char *inFileName, short inLineNum);//----------------------------------------------------------------------------------------// ThrowNewMessage_AC//----------------------------------------------------------------------------------------#define ThrowNewMessage_AC(err, old, newMsg) DebugThrowNewMessage_AC(err, old, newMsg, __FILE__, __LINE__)EXPORT_AC void DebugThrowNewMessage_AC(OSStatus inError, 									   CException_AC::Message oldMessage, 									   CException_AC::Message newMessage,									   const char *inFileName, short inLineNum);//----------------------------------------------------------------------------------------// ThrowIfBadAlloc_AC//----------------------------------------------------------------------------------------#define ThrowIfBadAlloc_AC(ptr) DebugThrowIfBadAlloc_AC((ptr), __FILE__, __LINE__)EXPORT_AC void DebugThrowIfBadAlloc_AC(const void* inPtr, const char* inFile, short inLine);//----------------------------------------------------------------------------------------// ThrowIfNULL_AC//----------------------------------------------------------------------------------------#define ThrowIfNULL_AC(ptr) DebugThrowIfBadAlloc_AC((ptr), __FILE__, __LINE__)inline void DebugThrowIfNULL_AC(const void* inPtr, const char* inFile, short inLine)	{ DebugThrowIfBadAlloc_AC(inPtr, inFile, inLine); }//----------------------------------------------------------------------------------------// ThrowIfBadCast_AC//----------------------------------------------------------------------------------------#define ThrowIfBadCast_AC(ptr) DebugThrowIfBadCast_AC((ptr), __FILE__, __LINE__)EXPORT_AC void DebugThrowIfBadCast_AC(const void* inPtr, const char* inFile, short inLine);#else//----------------------------------------------------------------------------------------// NonDebug Functions//----------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// ThrowIfError_AC//----------------------------------------------------------------------------------------	inline void ThrowIfError_AC(OSStatus inErr, CException_AC::Message msg){	if (inErr)		throw CException_AC(inErr, msg);}//----------------------------------------------------------------------------------------// ThrowIfError_AC//----------------------------------------------------------------------------------------inline void ThrowIfError_AC(OSStatus inErr) { 	if (inErr)		throw CException_AC(inErr); }//----------------------------------------------------------------------------------------// ThrowError_AC//----------------------------------------------------------------------------------------inline void ThrowError_AC(OSStatus inErr){		throw CException_AC(inErr);}//----------------------------------------------------------------------------------------// ThrowNewMessage_AC//----------------------------------------------------------------------------------------inline void ThrowNewMessage_AC(OSStatus inError, 							   CException_AC::Message oldMessage, 							   CException_AC::Message newMessage){	throw CException_AC(inError, oldMessage ? oldMessage : newMessage);}//----------------------------------------------------------------------------------------// ThrowNewMessage_AC//----------------------------------------------------------------------------------------inline void ThrowException_AC(OSStatus inError, CException_AC::Message inMsg){	throw CException_AC(inError, inMsg);}//----------------------------------------------------------------------------------------// Other (implementation has header dependencies so they're in the .cp file.)//----------------------------------------------------------------------------------------EXPORT_AC void ThrowIfMemError_AC();EXPORT_AC void ThrowIfNULLResource_AC(const void* r);inline void ThrowIfOSErr_AC(OSStatus error)	{ ThrowIfError_AC(error); }inline void ThrowIfBadOSStatus_AC(OSStatus error)	{ ThrowIfError_AC(error); }EXPORT_AC void ThrowIfNonObject_AC(const void* obj);EXPORT_AC void ThrowIfResError_AC();EXPORT_AC void ThrowIfBadAlloc_AC(const void* inPtr);inline void ThrowIfNULL_AC(const void* inPtr)	{ ThrowIfBadAlloc_AC(inPtr); }EXPORT_AC void ThrowIfBadCast_AC(const void* inPtr);#endif // qDebugExceptionsEXPORT_AC void ThrowBadAlloc_AC();EXPORT_AC void ThrowBadCast_AC();EXPORT_AC void ThrowLogicError_AC();EXPORT_AC void ThrowLogicError_AC(const char* what);EXPORT_AC void ThrowDomainError_AC();EXPORT_AC void ThrowDomainError_AC(const char* what);EXPORT_AC void ThrowInvalidArgument_AC();EXPORT_AC void ThrowInvalidArgument_AC(const char* what);EXPORT_AC void ThrowLengthError_AC();EXPORT_AC void ThrowLengthError_AC(const char* what);EXPORT_AC void ThrowOutOfRange_AC();EXPORT_AC void ThrowOutOfRange_AC(const char* what);EXPORT_AC void ThrowRuntimeError_AC();EXPORT_AC void ThrowRuntimeError_AC(const char* what);EXPORT_AC void ThrowOverflowError_AC();EXPORT_AC void ThrowOverflowError_AC(const char* what);EXPORT_AC void ThrowRangeError_AC();EXPORT_AC void ThrowRangeError_AC(const char* what);EXPORT_AC void ThrowUnderflowError_AC();EXPORT_AC void ThrowUnderflowError_AC(const char* what);#if qDebugExceptions >= qDebugLevelTwo_AC#define DoCatchMessage_AC(ex)				(ex).DoCatchMessage(__FILE__, __LINE__)#define DoCatchMessageAndStop_AC(ex)		(ex).DoCatchMessage(__FILE__, __LINE__, true)#define DoThrowMessage_AC(ex)				(ex).DoThrowMessage()// We can catch iso standard exceptions and foreign exceptions.#define DoCatchISOMessage_AC(ex)			CException_AC::DoCatchISOMessage(__FILE__, __LINE__, (ex))#define DoCatchISOMessageAndStop_AC(ex)		CException_AC::DoCatchISOMessage(__FILE__, __LINE__, (ex), true)#define DoCatchForeignMessage_AC()			CException_AC::DoCatchForeignMessage(__FILE__, __LINE__)#define DoCatchForeignMessageAndStop_AC()	CException_AC::DoCatchForeignMessage(__FILE__, __LINE__, true)#elseinline void ExceptionMessageStub_AC(CException_AC&) {}	// this should get optimized out of existance.inline void ISOExceptionMessageStub_AC(std::exception& /* exception */) {}inline void ForeignExceptionMessageStub_AC() {}	#define DoCatchMessage_AC(ex)				ExceptionMessageStub_AC((ex))#define DoCatchMessageAndStop_AC(ex)		ExceptionMessageStub_AC((ex))#define DoThrowMessage_AC(ex)				ExceptionMessageStub_AC((ex))	#define DoCatchISOMessage_AC(ex)			ISOExceptionMessageStub_AC((ex))#define DoCatchISOMessageAndStop_AC(ex)		ISOExceptionMessageStub_AC((ex))#define DoCatchForeignMessage_AC()			ForeignExceptionMessageStub_AC()#define DoCatchForeignMessageAndStop_AC()	ForeignExceptionMessageStub_AC()	#endif // qDebugExceptions >= qDebugLevelTwo_AC#endif // __CException_AC__